import json,html
from pathlib import Path
E=Path(__file__).resolve().parent
s=json.loads((E/'course-summary.json').read_text())
def num(v,d=2):return 'Not observed' if v is None else f'{v:.{d}f}'
def milestone(score,key):
 m=score.get('milestones',{}).get(key)
 return None if m is None else m['minutes']
names=['Entry → fortress','Y55 → fortress','High110 → fortress','Entry east 300','North 300','Fortress → bastion']
rows=[]
for p,name in zip(s['pairs'],names):
 b=next(e['result'] for e in s['entries'] if e['pair']==p['pair'] and e['arm']=='base');c=next(e['result'] for e in s['entries'] if e['pair']==p['pair'] and e['arm']=='candidate')
 bp=b['blocksPerMinute'];cp=c['blocksPerMinute']
 rows.append(f'<tr><th>{name}</th><td>{bp:.1f}</td><td>{cp:.1f}</td><td>{p['wallRatio']:.2f}×</td></tr>')
games=''
f=E/'game-comparison.json'
if f.exists():
 for r in json.loads(f.read_text()):
  cs=r['candidateScore'];bs=r['baseScore'];cm=r['candidateCommonMilestones'];common=r['candidateCommon']
  native=common.get('nativeDeaths');native=common['deaths'] if native is None else native
  data=[('Game window min',r['baselineObservedMinutes'],r['commonWindowMinutes'],r['candidatePlayedMinutes'],2),('Nether min',r['base']['netherMinutes'],common['netherMinutes'],r['candidate']['netherMinutes'],2),('Blocks / Nether min',r['base']['blocksPerNetherMinute'],common['blocksPerNetherMinute'],r['candidate']['blocksPerNetherMinute'],2),('First seen, min',milestone(bs,'fortressSeen'),cm['fortressSeen']['minutes'] if cm.get('fortressSeen') else None,milestone(cs,'fortressSeen'),2),('First entered, min',milestone(bs,'fortressEntered'),cm['fortressEntered']['minutes'] if cm.get('fortressEntered') else None,milestone(cs,'fortressEntered'),2),('Deaths',bs['deaths'],native,cs['deaths'],0)]
  gr=''.join(f'<tr><th>{label}</th><td>{num(b,d)}</td><td>{num(c,d)}</td><td>{num(full,d)}</td></tr>' for label,b,c,full,d in data)
  machine='Mini PC' if r['baselineMachine']=='mini' else 'Desktop (cached)'
  games+=f'''<section><h3>Seed {html.escape(r['seed'])}</h3><p class="small">Baseline: {machine}. Candidate: Mini PC. Common window: {r['commonWindowMinutes']:.2f} min.</p><table class="games"><thead><tr><th>Measure</th><th>Base</th><th>Travel<br>common</th><th>Travel<br>full</th></tr></thead><tbody>{gr}</tbody></table></section>'''
else:games='<p class="small">Live-game windows are still running. This preview is unpublished.</p>'
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Travel port measurements</title><style>
*{box-sizing:border-box}html,body{margin:0;background:transparent;color:var(--foreground,#172033);font-family:var(--font-sans,system-ui,sans-serif)}main{width:100%;padding:0}p{line-height:1.45;margin:8px 0}h2{font-size:19px;margin:0 0 8px}h3{font-size:16px;margin:0 0 5px}.small{font-size:12px;color:var(--muted-foreground,#626b7b)}.stats{display:grid;grid-template-columns:minmax(0,1.8fr) minmax(0,1fr);gap:18px;margin:18px 0}.value{font-size:26px;font-weight:700;letter-spacing:-.5px;font-variant-numeric:tabular-nums}.label{font-size:12px;color:var(--muted-foreground,#626b7b)}.warning{padding:16px;border-radius:var(--radius,10px);background:color-mix(in srgb,#e6a126 15%,transparent);color:inherit;border:1px solid color-mix(in srgb,#e6a126 45%,transparent);margin:16px 0}.warning strong{font-size:14px}.warning p{font-size:13px;margin-bottom:0}section{margin-top:24px}table{border-collapse:collapse;width:100%;table-layout:fixed;font-variant-numeric:tabular-nums;font-size:13px}th,td{padding:9px 6px;border-bottom:1px solid var(--border,#dbe1e9);text-align:right;vertical-align:middle}th:first-child{width:43%;text-align:left;font-weight:500;padding-left:0}thead th{font-size:11px;color:var(--muted-foreground,#626b7b);font-weight:600;text-align:right}thead th:first-child{font-weight:600}tfoot td,tfoot th{font-weight:700;border-top:2px solid var(--border,#dbe1e9);border-bottom:0}.games th:first-child{width:43%}.note{margin-top:12px;font-size:12px;color:var(--muted-foreground,#626b7b)}.mono{font-family:var(--font-mono,monospace);font-size:12px}@media(max-width:420px){table{font-size:12px}th,td{padding:8px 4px}.value{font-size:24px}.stats{gap:12px}th:first-child,.games th:first-child{width:40%}}
</style><main><h2>Measured travel pace</h2><p class="small"><span class="mono">4682f12e</span> → <span class="mono">6345839e</span> · Six fresh matched Mini PC pairs</p>'''
page+=f'''<div class="stats"><div><div class="value">{s['base']['pace']:.2f} → {s['candidate']['pace']:.2f}</div><div class="label">net blocks / active minute</div></div><div><div class="value">{s['comparison']['wallRatio']:.2f}×</div><div class="label">weighted pace gain</div></div></div><div class="warning"><strong>Zero-fire bar failed</strong><p>Both arms: 0 deaths and 0 lava samples. Base: 0 fire samples. Travel: one burn, 15 fire samples in Y55.</p></div><table><thead><tr><th>Course</th><th>Base</th><th>Travel</th><th>Gain</th></tr></thead><tbody>{''.join(rows)}</tbody><tfoot><tr><th>Weighted</th><td>{s['base']['pace']:.1f}</td><td>{s['candidate']['pace']:.1f}</td><td>{s['comparison']['wallRatio']:.2f}×</td></tr></tfoot></table><p class="note">Fresh world per arm, 4-CPU quota; JVM sees four processors. Game-clock gain: {s['comparison']['gameRatio']:.2f}×. One host-load flag; pair 3 baseline CPU sampling covers 50.5% of its run. TPS adjustment preserves all pace orderings. Neither arm arrived on a course.</p><section><h2>Live Sol games</h2><p class="small">Low effort, default tier, sequential 90-minute windows. Movement uses ten-second horizontal displacement per Nether minute. Fortress times use elapsed game-window minutes: visible bricks for seen, native advancement for entered. Not observed refers to the shown window.</p>{games}</section><p class="note">The 987654321 baseline has 44.76 minutes of usable cached Desktop capture and a different jar hash; class identity is unverified. Its native sampler has an 82.6-second maximum gap. Both baseline harnesses record 4682f12e. Loot salts differ between trials. Other cached d39 Nether-entry captures have no usable protocol. The Oct 25 Sol-stall window is excluded.</p><p class="note">Both native 90-minute runs retain INCOMPLETE and FAILED/TIMEOUT labels. The second records a non-terminal player-disappearance observer error; its timing is unverified. Candidate native sample gaps peak at 3.77 and 4.87 seconds.</p></main></html>'''
(E/'results.html').write_text(page)
print(E/'results.html')
